}

impl fmt::Display for SongCacheWriteError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::DirectoryHash(error) => write!(f, "could not hash song directory: {error}"),
